var e={material:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Збережені профілі філаменту - температури, густина та максимальний об’ємний потік, який кожен з них витримує.`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Додати матеріал`}},loading:{t:0,b:{t:2,i:[{t:3}],s:`Завантаження…`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Поки що немає матеріалів. Додайте перший, щоб почати створювати свою бібліотеку філаменту.`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Редагувати`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Видалити`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Зберегти`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Скасувати`}},list:{flow:{t:0,b:{t:2,i:[{t:4,k:`v`},{t:3,v:` mm³/s`}]}}},fields:{name:{t:0,b:{t:2,i:[{t:3}],s:`Назва`}},material:{t:0,b:{t:2,i:[{t:3}],s:`Тип`}},brand:{t:0,b:{t:2,i:[{t:3}],s:`Бренд`}},color:{t:0,b:{t:2,i:[{t:3}],s:`Колір`}},diameter:{t:0,b:{t:2,i:[{t:3}],s:`Діаметр (mm)`}},density:{t:0,b:{t:2,i:[{t:3}],s:`Густина (g/cm³)`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Макс. об’ємний потік (mm³/s)`}},nozzleTemp:{t:0,b:{t:2,i:[{t:3}],s:`Сопло (°C)`}},bedTemp:{t:0,b:{t:2,i:[{t:3}],s:`Стіл (°C)`}},notes:{t:0,b:{t:2,i:[{t:3}],s:`Нотатки`}}},flowCheck:{exceeds:{t:0,b:{t:2,i:[{t:3,v:`Перевищує межу `},{t:4,k:`hotend`},{t:3,v:` (`},{t:4,k:`flow`},{t:3,v:` > `},{t:4,k:`ceiling`},{t:3,v:` mm³/s)`}]}},within:{t:0,b:{t:2,i:[{t:4,k:`headroom`},{t:3,v:`% під межею `},{t:4,k:`hotend`}]}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Довідка`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Довідник Material Brain`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Закрити`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що таке Material Brain?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Бібліотека ваших філаментів. Кожен профіль зберігає температури, густину та максимальний об’ємний потік, який витримує філамент - числа, на яких ґрунтуються налаштування та слайсинг.`}}},flow:{title:{t:0,b:{t:2,i:[{t:3}],s:`Потік проти межі хотенда`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Максимальний об’ємний потік кожного профілю звіряється з межею хотенда з каталогу, тож профіль, який вимагає більше, ніж хотенд здатен розплавити, позначається ще до того, як це проявиться як недоекструзія.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Глосарій`}}}},glossary:{volumetricFlow:{term:{t:0,b:{t:2,i:[{t:3}],s:`Об’ємний потік`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Скільки пластику (mm³) хотенд розплавляє за секунду - реальна межа швидкості для швидкого друку.`}}},density:{term:{t:0,b:{t:2,i:[{t:3}],s:`Густина`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Маса філаменту на об’єм (g/cm³); використовується для переведення об’ємного потоку в масову витрату.`}}},ceiling:{term:{t:0,b:{t:2,i:[{t:3}],s:`Межа хотенда`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Максимальний об’ємний потік, який витримує хотенд, з каталогу обладнання.`}}}}},apply:{button:{t:0,b:{t:2,i:[{t:3}],s:`Прогрів`}},applied:{t:0,b:{t:2,i:[{t:3,v:`Нагрівання `},{t:4,k:`name`},{t:3,v:` до `},{t:4,k:`nozzle`},{t:3,v:`°C сопло / `},{t:4,k:`bed`},{t:3,v:`°C стіл`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Принтер зайнятий - зараз прогрів неможливий`}},no_temps:{t:0,b:{t:2,i:[{t:3}],s:`Для цього профілю не задано температур`}},error:{t:0,b:{t:2,i:[{t:3,v:`Не вдалося прогріти: `},{t:4,k:`error`}]}}}}};export{e as default};